WITH bounds AS (
 SELECT CASE WHEN MIN(bucket) IS NULL THEN NULL ELSE GREATEST(MIN(bucket),(CASE ${window:sqlstring} WHEN 'week' THEN date_trunc('week',NOW() AT TIME ZONE 'Europe/London') AT TIME ZONE 'Europe/London' WHEN 'month' THEN date_trunc('month',NOW() AT TIME ZONE 'Europe/London') AT TIME ZONE 'Europe/London' ELSE '-infinity'::timestamptz END)) END AS first_day
 FROM history.daily_rollup WHERE asset_id=${asset:sqlstring}
), expected AS (
 SELECT SUM(EXTRACT(EPOCH FROM (((day+INTERVAL '1 day') AT TIME ZONE 'Europe/London')-(day AT TIME ZONE 'Europe/London')))/600.0) AS n
 FROM bounds,LATERAL generate_series(first_day AT TIME ZONE 'Europe/London',(NOW() AT TIME ZONE 'Europe/London')::date::timestamp,INTERVAL '1 day') day
)
SELECT 100.0*SUM(valid_power_count)/(SELECT NULLIF(n,0) FROM expected) AS coverage_pct
FROM history.daily_rollup WHERE asset_id=${asset:sqlstring} AND bucket>=(CASE ${window:sqlstring} WHEN 'week' THEN date_trunc('week',NOW() AT TIME ZONE 'Europe/London') AT TIME ZONE 'Europe/London' WHEN 'month' THEN date_trunc('month',NOW() AT TIME ZONE 'Europe/London') AT TIME ZONE 'Europe/London' ELSE '-infinity'::timestamptz END) AND bucket<NOW()
